add_action( 'woocommerce_after_add_to_cart_form', 'perfectpixel_attributes_follow_selection' );

function perfectpixel_attributes_follow_selection() {
	global $product;
	if ( ! $product || ! $product->is_type( 'variable' ) ) {
		return;
	}
	?>
	<script>
	jQuery( function ( $ ) {
		var form = $( 'form.variations_form' );
		var cell = function ( name ) {
			// "attribute_pa_color" -> table row ".woocommerce-product-attributes-item--attribute_pa_color".
			return $( '.woocommerce-product-attributes-item--' + name + ' .woocommerce-product-attributes-item__value' );
		};
		form.find( 'table.variations select' ).each( function () {
			var td = cell( $( this ).attr( 'name' ) );
			td.data( 'perfectpixel-original', td.html() );
		} );
		form.on( 'found_variation', function () {
			form.find( 'table.variations select' ).each( function () {
				var select = $( this );
				if ( select.val() ) {
					cell( select.attr( 'name' ) ).text( select.find( 'option:selected' ).text() );
				}
			} );
		} ).on( 'reset_data', function () {
			form.find( 'table.variations select' ).each( function () {
				var td = cell( $( this ).attr( 'name' ) );
				if ( undefined !== td.data( 'perfectpixel-original' ) ) {
					td.html( td.data( 'perfectpixel-original' ) );
				}
			} );
		} );
	} );
	</script>
	<?php
}
